"""Reproject existing cube faces, rectify wall-only regions, cache derivative textures."""
import hashlib,json,math
from pathlib import Path
import cv2,numpy as np
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];S=ROOT/'.campus-cache/photo-projection';A=S/'assets';A.mkdir(parents=True,exist_ok=True);cp=ROOT/'configs/photo-projection-library.json';cfg=json.loads(cp.read_text());src=Path('/workspace/henan_campus/resources/panorama_cubefaces')/cfg['panorama_scene'];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();source_hashes={name:sha(src/(name+'.jpg')) for name in ['f','b','l','r','u','d']};fingerprint=hashlib.sha256((sha(cp)+sha(Path(__file__))+json.dumps(source_hashes,sort_keys=True)+cv2.__version__).encode()).hexdigest();receipt=S/'materials.json'
if receipt.exists():
 old=json.loads(receipt.read_text())
 if old.get('fingerprint')==fingerprint and all((A/n).exists() and sha(A/n)==h for n,h in old['textures'].items()):print('PHOTO_PROJECTION_TEXTURES_CACHED');raise SystemExit(0)
w,h=cfg['view']['size'];yaw,pitch,fov=[math.radians(cfg['view'][k]) for k in ['yaw_deg','pitch_deg','horizontal_fov_deg']];f=np.array([math.sin(yaw)*math.cos(pitch),math.sin(pitch),math.cos(yaw)*math.cos(pitch)]);right=np.array([math.cos(yaw),0,-math.sin(yaw)]);up=np.cross(f,right);x=(np.arange(w)+.5-w/2)/(w/2)*math.tan(fov/2);y=-(np.arange(h)+.5-h/2)/(w/2)*math.tan(fov/2);rays=f+right*x[None,:,None]+up*y[:,None,None];dx,dy,dz=np.moveaxis(rays,-1,0);axis=np.abs(rays).argmax(axis=-1);image=np.zeros((h,w,3),np.uint8)
for name,mask,u,v in [('f',(axis==2)&(dz>0),dx/np.maximum(abs(dz),1e-8),-dy/np.maximum(abs(dz),1e-8)),('b',(axis==2)&(dz<0),-dx/np.maximum(abs(dz),1e-8),-dy/np.maximum(abs(dz),1e-8)),('l',(axis==0)&(dx<0),dz/np.maximum(abs(dx),1e-8),-dy/np.maximum(abs(dx),1e-8)),('r',(axis==0)&(dx>0),-dz/np.maximum(abs(dx),1e-8),-dy/np.maximum(abs(dx),1e-8)),('u',(axis==1)&(dy>0),dx/np.maximum(abs(dy),1e-8),dz/np.maximum(abs(dy),1e-8)),('d',(axis==1)&(dy<0),dx/np.maximum(abs(dy),1e-8),-dz/np.maximum(abs(dy),1e-8))]:
 if not mask.any():continue
 raw=np.array(Image.open(src/(name+'.jpg')).convert('RGB'));pixels=cv2.remap(raw,np.float32((u+1)*.5*(raw.shape[1]-1)),np.float32((v+1)*.5*(raw.shape[0]-1)),cv2.INTER_LINEAR,borderMode=cv2.BORDER_REPLICATE);image[mask]=pixels[mask]
Image.fromarray(image).save(S/'reference-private.png');checks=[]
for i,(quad,size) in enumerate(zip(cfg['facade_quads'],cfg['texture_sizes'])):
 q=np.float32(quad);assert cv2.isContourConvex(q.astype('int32'));width,height=size;target=np.float32([[0,0],[width-1,0],[width-1,height-1],[0,height-1]]);H=cv2.getPerspectiveTransform(q,target);out=cv2.warpPerspective(image,H,(width,height),flags=cv2.INTER_CUBIC,borderMode=cv2.BORDER_REPLICATE);hsv=cv2.cvtColor(out,cv2.COLOR_RGB2HSV);green=float(np.mean((hsv[:,:,0]>35)&(hsv[:,:,0]<90)&(hsv[:,:,1]>65)&(hsv[:,:,2]>40)));assert green<.015,'Foreground foliage entered the facade crop'
 p=A/('library-facade-'+str(i)+'.jpg');Image.fromarray(out).save(p,quality=88,optimize=True,subsampling=0);Image.fromarray(out).resize((width//2,height//2),Image.Resampling.LANCZOS).save(A/('library-coarse-'+str(i)+'.jpg'),quality=82,optimize=True);checks.append({'segment':i,'homography':H.tolist(),'corner_reprojection_error_px':float(np.max(np.linalg.norm(cv2.perspectiveTransform(q[None],H)[0]-target,axis=1))),'green_pixel_fraction':green,'dimensions':size,'sha256':sha(p)})
q=np.float32(cfg['paving_quad']);H=cv2.getPerspectiveTransform(q,np.float32([[0,0],[255,0],[255,255],[0,255]]));raw=np.array(Image.open(src/'d.jpg').convert('RGB'));paving=cv2.warpPerspective(raw,H,(256,256),flags=cv2.INTER_CUBIC);Image.fromarray(paving).save(A/'library-pavers.png',optimize=True)
textures={p.name:sha(p) for p in A.iterdir() if p.suffix in ['.jpg','.png']};total=sum((A/n).stat().st_size for n in textures);assert total<cfg['budget']['maximum_texture_bytes'];report={'passed':True,'fingerprint':fingerprint,'source_scene':cfg['panorama_scene'],'source_face_hashes':source_hashes,'checks':checks,'textures':textures,'texture_bytes':total,'original_full_photos_published':False,'source_lighting':'CAPTURED_IN_PHOTO_NOT_NEW_PHYSICAL_RELIGHTING','limitations':cfg['quality_limits'],'permission':cfg['permission']};receipt.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print('PHOTO_PROJECTION_TEXTURES_READY',total)
